namespace RisingLands;
public sealed partial class Simulation {
    public void Stop(Actor u){if(u.Type==17&&Ocean.Jobs.Any(j=>j.Balloon==u.Slot&&j.Stage>0))return;Ocean.Jobs.RemoveAll(j=>j.Actor==u.Slot&&j.Stage<2);if(u.Owner!=0||!VisualCatalog.Visible(u))return;u.DefenseAcquireAfter=Tick+30;u.AutomaticDefense=false;u.DefenseAnchor=-1;u.CombatRetryAt=0;Opponent.Sieges.Remove(u.Slot);Opponent.Repairs.Remove(u.Slot);CancelFeeding(u);CancelSpecialOrder(u);u.PersistentCollection=false;u.OverflowCell=-1;u.FoodSourceBuilding=u.FoodSource=u.FoodField=-1;if(u.Rock==0)u.MineIndex=-1;else u.RepeatMine=false;u.FoodPlantsOnly=false;ResidentTrips.RemoveAll(j=>j.Slot==u.Slot);u.MineJob=0;u.MineTicks=0;CancelResearchTrip(u);u.AttackWindup=0;u.AttackTarget=-1;u.Route.Clear();u.FoodJob=0;u.WorkTicks=0;DetachBuilder(u.Slot);}
    public int OrderGroup(IEnumerable<Actor> actors,int x,int y){if(x<0||y<0||x>=World.Width||y>=World.Height)return 0;var used=new HashSet<int>();int count=0;var destinations=new List<(int x,int y)>();for(int radius=0;radius<=4;radius++)for(int dy=-radius;dy<=radius;dy++)for(int dx=-radius;dx<=radius;dx++)if(Math.Max(Math.Abs(dx),Math.Abs(dy))==radius)destinations.Add((x+dx,y+dy));
        foreach(var u in actors.Where(u=>u.Owner==0&&VisualCatalog.Visible(u)).DistinctBy(u=>u.Slot).OrderBy(u=>u.Slot))foreach(var p in destinations){if(!CanTraverse(u,p.x,p.y))continue;int cell=p.y*256+p.x;if(used.Contains(cell)||!Order(u,p.x,p.y))continue;used.Add(cell);count++;break;}return count;
    }
    public string Activity(Actor u){if(u.Health<=0)return "Unidade derrotada";if(u.AttackTarget>=0)return u.Route.Count>0?"Aproximando do alvo":"Em combate";var site=Constructions.FirstOrDefault(c=>HasBuilder(c,u.Slot)&&!Complete(c));if(site!=null)return u.Route.Count>0?"Indo para a obra":"Construindo: "+site.Progress*100/Rule(site.Type).Duration+"%";if(u.MineJob!=0)return MiningStatus(u);return u.FoodJob!=0?FoodStatus(u):u.Route.Count>0?"Em movimento":FoodStatus(u);}
}
